code='''def transform(grid):
    cells = {(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 8}
    h, w = len(grid), len(grid[0])
    placements = []
    # The 2x2 block is color 1. The three L orientations map to colors 2, 3, and 4.
    shapes = {
        2: ((0, 1), (1, 0), (1, 1)),
        3: ((0, 0), (0, 1), (1, 1)),
        4: ((0, 0), (1, 0), (1, 1)),
    }
    for r in range(h - 1):
        for c in range(w - 1):
            block = {(r + dr, c + dc) for dr in range(2) for dc in range(2)}
            if block <= cells:
                placements.append((1, block))
            for color, shape in shapes.items():
                part = {(r + dr, c + dc) for dr, dc in shape}
                if part <= cells:
                    placements.append((color, part))

    def cover(remaining):
        if not remaining:
            return []
        cell = min(remaining)
        for color, part in placements:
            if cell in part and part <= remaining:
                rest = cover(remaining - part)
                if rest is not None:
                    return [(color, part)] + rest
        return None

    solution = cover(cells)
    if solution is None:
        raise ValueError("No tiling by the demonstrated colored shapes")
    out = [[0 for _ in row] for row in grid]
    for color, part in solution:
        for r, c in part:
            out[r][c] = color
    return out
'''
